// ============================================================================
// Internal structures
// ============================================================================

// Trampoline structure - holds relocated instructions + jump back
struct Trampoline {
    uint8_t* code;           // Executable memory for trampoline
    size_t code_size;        // Total allocated size
    size_t used_size;        // Actually used bytes
    size_t insn_count;       // Number of relocated instructions
};

// Hook context - complete hook state
struct HookContext {
    void* target;            // Original function address
    void* detour;            // Hook function address
    Trampoline trampoline;   // Trampoline for calling original

    uint8_t original_bytes[32];  // Saved original bytes
    uint8_t hook_bytes[32];      // Hook jump sequence
    size_t hook_size;            // Size of hook (bytes overwritten)

    bool enabled;            // Is hook currently active?
    bool valid;              // Is hook context valid?
};

// Global state
struct HookState {
    bool initialized = false;
    HookConfig config;
    std::mutex mutex;
    std::vector<HookContext*> hooks;
    std::unordered_map<void*, HookContext*> target_map;
};

static HookState g_state;

#ifndef VEDA64_NO_STRINGS
// ============================================================================
// Status to string
// ============================================================================

const char* status_to_string(HookStatus status) {
    switch (status) {
        case HookStatus::Success: return "Success";
        case HookStatus::NotInitialized: return "Hooking subsystem not initialized";
        case HookStatus::InvalidTarget: return "Invalid target address";
        case HookStatus::InvalidDetour: return "Invalid detour address";
        case HookStatus::AllocationFailed: return "Memory allocation failed";
        case HookStatus::ProtectionFailed: return "Memory protection change failed";
        case HookStatus::DisassemblyFailed: return "Instruction disassembly failed";
        case HookStatus::RelocationFailed: return "Instruction relocation failed";
        case HookStatus::InstructionTooComplex: return "Instruction too complex to relocate";
        case HookStatus::HookAlreadyInstalled: return "Hook already installed at target";
        case HookStatus::HookNotFound: return "Hook not found";
        case HookStatus::HookDisabled: return "Hook is disabled";
        case HookStatus::InternalError: return "Internal error";
        default: return "Unknown error";
    }
}
#endif // VEDA64_NO_STRINGS

// ============================================================================
// Configuration
// ============================================================================

void set_config(const HookConfig& config) {
    std::lock_guard<std::mutex> lock(g_state.mutex);
    g_state.config = config;
}

HookConfig get_config() {
    std::lock_guard<std::mutex> lock(g_state.mutex);
    return g_state.config;
}

// ============================================================================
// Initialization
// ============================================================================

HookStatus initialize() {
    std::lock_guard<std::mutex> lock(g_state.mutex);

    if (g_state.initialized) {
        return HookStatus::Success;
    }

    // Initialize allocation granularity from system info
    init_allocation_granularity();

    // Set default config
    g_state.config = HookConfig{};
    g_state.initialized = true;

    return HookStatus::Success;
}

void shutdown() {
    std::lock_guard<std::mutex> lock(g_state.mutex);

    if (!g_state.initialized) {
        return;
    }

    // Remove all hooks (unlock to avoid deadlock)
    g_state.mutex.unlock();
    remove_all();
    g_state.mutex.lock();

    g_state.initialized = false;
}

bool is_initialized() {
    std::lock_guard<std::mutex> lock(g_state.mutex);
    return g_state.initialized;
}

